39	ColumnPtr IColumn::createWithOffsets(const Offsets & offsets, const Field & default_field, size_t total_rows, size_t shift) const
40	{
41	    if (offsets.size() + shift != size())
42	        throw Exception(ErrorCodes::LOGICAL_ERROR,
43	            "Incompatible sizes of offsets ({}), shift ({}) and size of column {}", offsets.size(), shift, size());
44	
45	    auto res = cloneEmpty();
46	    res->reserve(total_rows);
47	
48	    ssize_t current_offset = -1;
49	    for (size_t i = 0; i < offsets.size(); ++i)
50	    {
51	        ssize_t offsets_diff = static_cast<ssize_t>(offsets[i]) - current_offset;
52	        current_offset = offsets[i];
53	
54	        if (offsets_diff > 1)
55	            res->insertMany(default_field, offsets_diff - 1);
56	
57	        res->insertFrom(*this, i + shift);
58	    }
59	
60	    ssize_t offsets_diff = static_cast<ssize_t>(total_rows) - current_offset;
61	    if (offsets_diff > 1)
62	        res->insertMany(default_field, offsets_diff - 1);
63	
64	    return res;
65	}
